SELECT cms.content_item_create(cms.section_id_for('about', 'about-life'), 'slides', NULL, pg_temp.seed_media($j${"title":"Weekend Vibes","body":"Before the launch of our employee engagement initiative, it was observed that the employees went through immense work stress, and there was no pause from this hectic routine. Taking this work culture into consideration, the employee engagement team came up with the idea of Weekend Vibes. Despite having Employees with extraordinary talents, they didn’t have a platform to display them. Weekend Vibes was launched for employees to participate in activities like Karaoke, Bollywood Quizzes, Bolly-fit Dance Fitness sessions, and Paint Their Hearts Out at corporate office as pilot project. After witnessing fabulous participation, we intend to extend same across other locations soon.","photo_media":"@media:/figma/about/life/photo-2.png","back_photo_media":"@media:/figma/about/life/photo-1.png"}$j$::jsonb), 1);
